//! 🧪️ Artboard fields expose a localized disabled reason until genuine child capability is connected.
use super::*;
#[test]
fn page_drawing_controls_do_not_invent_unqualified_child_metadata(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let transport:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧬️schema/🧬️mutations/🖊️set-page-background-drawing/🧪️tests/🔣️transport.json")).unwrap();let member:semio_s_artifact_layout_layout_model::LayoutDrawingMember=semio_framework_pack_json::from_json_str(&transport["cases"][0]["input"]["SetPageBackgroundDrawing"]["drawing"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut snapshot=semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document();snapshot.background_drawing=Some(member.clone());snapshot.pages[0].background_drawing=Some(member);for locale in fixture["locales"].as_array().unwrap(){let view=semio_framework_plugin::ViewModel::new(semio_framework_ui_locale::Locale::from_language_tag(locale.as_str().unwrap()).unwrap(),semio_framework_ui_locale::Terminology::Native);let labels=crate::terminology::layout_labels(&view);let config=LayoutWindowConfig{active_page_id:snapshot.pages[0].id.clone(),..Default::default()};let node=render(&snapshot,&config,&LayoutInteractionSnapshot::default(),labels,&semio_framework_plugin::TreeWindows::for_body(&view,LAYOUT_PLAY_BODY_INSPECTION)).unwrap();let mut pending=vec![&node];let mut fields=0;let mut copy=0;while let Some(row)=pending.pop(){if row.key.as_str()=="layout-play-inspector.patchPage.copyDocumentDrawing.input"{assert!(row.disabled);assert!(row.bindings.is_empty());copy+=1;}if row.key.as_str().starts_with("layout-play-inspector.page-drawing.")&&row.key.as_str().ends_with(".input"){assert!(row.disabled);assert!(row.bindings.is_empty());let semio_framework_plugin::Component::Input(input)=&row.component else{panic!("numeric artboard field")};assert!(input.value.as_str().is_empty());fields+=1}pending.extend(row.children.iter())}assert_eq!(copy,1);assert_eq!(fields,fixture["fields"].as_array().unwrap().len());let json=semio_framework_plugin::artifact_app_laws::project_and_retire_fixture_tree(semio_framework_plugin::built_to_component_tree(node)).unwrap();assert!(json.contains(labels.drawing_canvas_unavailable.as_str()));assert!(json.contains(labels.drawing_copy_unavailable.as_str()));}}
